import{readFile,writeFile}from'node:fs/promises';import{createHash}from'node:crypto';const before=JSON.parse(await readFile('.local/sequence-navigation/project-before.json','utf8'));const data=JSON.parse(await readFile(before.path,'utf8'));const hash=v=>createHash('sha256').update(JSON.stringify(v)).digest('hex');if(hash(data.scenes)!==before.scenesHash||hash(data.transcriptionJobs)!==before.transcriptHash)throw Error('Project content changed');const r=await fetch('http://localhost:3211/',{signal:AbortSignal.timeout(3000)});await r.body.cancel();await writeFile('.local/sequence-navigation/preservation-final.json',JSON.stringify({sceneCount:data.scenes.length,scenesUnchanged:true,transcriptUnchanged:true,httpStatus:r.status}));console.log({sceneCount:data.scenes.length,scenesUnchanged:true,transcriptUnchanged:true,httpStatus:r.status});
